import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"管理直播连接","description":"","frontmatter":{"title":"管理直播连接","docId":"user.live.connections","translationKey":"user.live.connections","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"446118d4c202b645dd93867f1715484cbd9876f940ba229ac26e4b7f24bc4cbc","translationRevision":"8424562b5daf6456792d7c1035b284535552166887f745d2079e4511f8a31db1","order":10},"headers":[],"relativePath":"zh/user/live/connections.md","filePath":"zh/user/live/connections.md","lastUpdated":1795735295000}`),s={name:`zh/user/live/connections.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="manage-live-connections" tabindex="-1">管理直播连接 <a class="header-anchor" href="#manage-live-connections" aria-label="Permalink to “管理直播连接”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目标与前置条件”">​</a></h2><p>连接指定主播，了解重新连接的行为，并单独配置插件服务器。你需要正常的<a href="./../installation.html">桌面安装</a>、网络访问和主播账号名。诊断操作系统问题前，请先查看<a href="./../requirements.html">系统要求</a>。</p><h2 id="connect-deliberately" tabindex="-1">按步骤建立连接 <a class="header-anchor" href="#connect-deliberately" aria-label="Permalink to “按步骤建立连接”">​</a></h2><ol><li>打开 <strong>连接</strong>。输入账号名，可带或不带 <code>@</code>；显示名称并不是同一个标识符。</li><li>先关闭 <strong>使用会话 Cookie</strong>。如果 TikTok 需要授权会话，再启用并仅在遮蔽内容的字段中输入 Cookie。Cookie 只保存在内存中，不要粘贴到诊断信息或 Cloud 设置中。</li><li>直接尝试连接时，保持 <strong>监控并自动连接</strong> 关闭，再选择 <strong>连接</strong>。重试前，阅读状态和错误信息。</li><li>在<a href="./feed.html">直播事件流</a>中检查主播是否正确，以及是否收到新事件。已连接但没有互动的直播间可能不显示活动。</li><li>对同一主播使用 <strong>重新连接</strong>；切换主播前使用 <strong>断开连接</strong>。连接尝试忙碌时，<strong>取消</strong> 可停止该次尝试。</li></ol><p>直接连接成功后，可启用监控以等待主播开播。等待与检查不同于已连接。编辑锁定的账号名前，请先停止监控。选择最近的主播会立即开始连接，并非仅填入输入框。</p><p>探索器会提供发现的直播间，但结果可能过时。请先刷新，再判断直播间是否仍可用。下方面板中的插件服务器连接用于配置各自的服务；插件已连接并不代表 TikTok 或 Cloud 已通过身份验证。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “预期结果与状态”">​</a></h2><p>直接连接、监控及插件连接控件均可使用。重新连接同一主播会保留当前事件流上下文；切换主播会开始另一个上下文。实际能否访问 TikTok 取决于上游直播间和会话，本地测试成功并不构成保证。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to “恢复方法”">​</a></h2><p>直播间离线时，请确认主播已经开播。会话或限流错误请遵循显示的重试条件。反复点击重新连接不会刷新身份验证。通过<a href="./../preferences/troubleshooting.html">故障排查</a>收集故障组件及发生时间，不要泄露凭据。</p><p>在改动真实配置之前先交互式试用:</p>`,12),t(d,{scenario:`connection`,locale:`zh`,panel:`connection`,title:`试用 LIVE 连接面板`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">命令行操作 <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “命令行操作”">​</a></h2><p>本指南中的每个操作也可通过 CLI 使用——离线、可编写脚本、适合代理。用法行是解析器语法,在所有语言中保持英文。</p><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools live connect --unique-id &lt;id&gt; --session-cookie &lt;cookie&gt; [--room-id &lt;id&gt;]</code></td><td>连接到直播房间</td></tr><tr><td><code>tiktools live pick --session-cookie &lt;cookie&gt;</code></td><td>交互式选择直播房间</td></tr><tr><td><code>tiktools live channels [--keyword text] [--offset N] [--limit N] [--session-cookie &lt;cookie&gt;]</code></td><td>发现直播频道；无需会话即可工作</td></tr><tr><td><code>tiktools live disconnect</code></td><td>断开当前房间的连接 <strong>破坏性</strong></td></tr><tr><td><code>tiktools live status</code></td><td>当前连接状态</td></tr></tbody></table><p>查看<a href="./../../developer/cli.html">完整命令参考</a>了解约定、JSON 输出和破坏性操作标记。</p>`,4)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};